    [Fact]
    public void ReferenceSnapshotRetainsConsumedAncestorOverrideWithoutAdvancingOriginal()
    {
        var tracker = new DocxportNet.Walker.DxpListTracker();
        SeedChild(tracker, childOverride: true);
        var snapshot = tracker.CopyForReference();
        Assert.Equal(43, snapshot.NextIndex(1, 1, 0, 42, true));
        Assert.Equal(43, tracker.NextIndex(1, 1, 0, 42, true));
    }

    [Fact]
    public void ClearAllDiscardsConsumedAncestorOverride()
    {
        var tracker = new DocxportNet.Walker.DxpListTracker();
        SeedChild(tracker, childOverride: true);
        tracker.ClearAll();
        SeedChild(tracker, childOverride: false);
        Assert.Equal(42, tracker.NextIndex(1, 1, 0, 42, true));
    }

    private static void SeedChild(DocxportNet.Walker.DxpListTracker tracker, bool childOverride)
    {
        tracker.NextIndex(1, 1, 1, childOverride ? 17 : 3, childOverride,
            new[] { -1, 0 }, new[] { 42, childOverride ? 17 : 3 }, new[] { true, childOverride });
        Assert.Equal(7, tracker.SeedUnstartedAncestor(1, 1, 0, 7, false, 42));
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void SeededAncestorOverrideActivationMatchesWord(string name, string stylesXml,
        string documentXml, string numberingXml, string expected)
    {
        using var stream = new MemoryStream();
        using var document = WordprocessingDocument.Create(stream, WordprocessingDocumentType.Document);
        var main = document.AddMainDocumentPart();
        main.Document = new Document(documentXml);
        main.AddNewPart<StyleDefinitionsPart>().Styles = new Styles(stylesXml);
        main.AddNewPart<NumberingDefinitionsPart>().Numbering = new Numbering(numberingXml);
        Assert.Empty(new DocumentFormat.OpenXml.Validation.OpenXmlValidator(FileFormatVersions.Office2013).Validate(document));
        _ = main.Document.Descendants().ToArray();
        _ = main.StyleDefinitionsPart.Styles.Descendants().ToArray();
        _ = main.NumberingDefinitionsPart.Numbering.Descendants().ToArray();
        var before = new[] { main.Document.OuterXml, main.StyleDefinitionsPart.Styles.OuterXml, main.NumberingDefinitionsPart.Numbering.OuterXml };
        DxpITextVisitor[] visitors = [new DxpMarkdownVisitor(DxpMarkdownVisitorConfig.CreatePlainConfig()),
            new DxpHtmlVisitor(DxpHtmlVisitorConfig.CreatePlainConfig()),
            new DxpPlainTextVisitor(DxpPlainTextVisitorConfig.CreateAcceptConfig())];
        foreach (var visitor in visitors)
        {
            var output = DxpExport.ExportToString(document, visitor);
            if (visitor is DxpHtmlVisitor) output = new HtmlParser().ParseDocument(output).Body!.TextContent;
            var actual = string.Join(" ", Regex.Matches(output, @"(?:L[012]=)?[-0-9]+\.?(?=\s*Item[012])")
                .Cast<Match>().Select(match => match.Value));
            Assert.Equal(expected, actual);
        }
        Assert.Equal(before, new[] { main.Document.OuterXml, main.StyleDefinitionsPart.Styles.OuterXml, main.NumberingDefinitionsPart.Numbering.OuterXml });
    }
